import { useId, useMemo, useState } from "react"
import { ExternalLink } from "lucide-react"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { SettingsControlField } from "@/components/settings-form/SettingsControlField"
import { getAdminParams } from "@/lib/admin-params"
import {
  activateLicense,
  deactivateLicense,
  MapSVGApiError,
  maskLicenseKey,
  type LicenseMutationResponse,
} from "@/lib/global-settings-api"

type LicenseViewState = {
  ok: boolean
  message: string
  code: string
  warning: string
  warningCode: string
  domainsUsed: number | null
  domainsMax: number | null
}

function apiErrorCode(error: unknown): string {
  if (!(error instanceof MapSVGApiError) || !error.payload) return ""
  return typeof error.payload.code === "string" ? error.payload.code : ""
}

function errorText(error: unknown, fallback: string): string {
  return error instanceof Error && error.message ? error.message : fallback
}

function isDomainActionCode(code: string): boolean {
  return [
    "domain_blocked",
    "domain_limit",
    "domain_mismatch",
    "domain_not_registered",
    "localhost_pending",
    "localhost_limit",
  ].includes(code)
}

function licenseWarningText(status: LicenseViewState): string {
  if (status.warningCode !== "domain_limit") return status.warning
  if (status.domainsUsed != null && status.domainsMax != null) {
    return (
      "Domain limit reached (" +
      status.domainsUsed +
      "/" +
      status.domainsMax +
      "). Review your registered domains in MapSVG Dashboard."
    )
  }
  return (
    status.warning || "Domain limit reached. Review your registered domains in MapSVG Dashboard."
  )
}

export function LicenseSettingsPage({ activationOnly = false }: { activationOnly?: boolean }) {
  const licenseInputId = useId()
  const params = useMemo(() => getAdminParams(), [])
  const options =
    params.options && typeof params.options === "object"
      ? (params.options as Record<string, unknown>)
      : {}
  const initialRawKey =
    typeof options.purchase_code === "string" ? options.purchase_code.trim() : ""

  const [rawKey, setRawKey] = useState(initialRawKey)
  const [maskedKey, setMaskedKey] = useState(
    params.license?.maskedKey || maskLicenseKey(initialRawKey),
  )
  const [hasCode, setHasCode] = useState(params.license?.hasCode ?? Boolean(initialRawKey))
  const [status, setStatus] = useState<LicenseViewState>({
    ok: params.license?.ok ?? false,
    message: params.license?.message ?? "",
    code: params.license?.code ?? "",
    warning: params.license?.warning ?? "",
    warningCode: params.license?.warningCode ?? "",
    domainsUsed: params.license?.domainsUsed ?? null,
    domainsMax: params.license?.domainsMax ?? null,
  })
  const [editing, setEditing] = useState(!hasCode)
  const [licenseKey, setLicenseKey] = useState("")
  const [busy, setBusy] = useState(false)
  const [transientError, setTransientError] = useState("")
  const [successMessage, setSuccessMessage] = useState("")

  const applySuccess = (key: string, data: LicenseMutationResponse, recheck: boolean) => {
    setRawKey(key)
    setMaskedKey(maskLicenseKey(key))
    setHasCode(true)
    setEditing(false)
    setLicenseKey("")
    setTransientError("")
    setStatus({
      ok: true,
      message: "",
      code: "",
      warning: data.warning ?? "",
      warningCode: data.warningCode ?? "",
      domainsUsed: data.domainsUsed ?? null,
      domainsMax: data.domainsMax ?? null,
    })
    setSuccessMessage(
      recheck
        ? "License is valid. Domain settings are up to date."
        : "MapSVG is activated. Automatic updates are enabled on the WordPress Plugins page.",
    )
  }

  const validateKey = async (key: string, recheck = false) => {
    const value = key.trim()
    if (!value) {
      setTransientError("Enter a license key.")
      return
    }

    setBusy(true)
    setTransientError("")
    setSuccessMessage("")
    try {
      const data = await activateLicense(value)
      applySuccess(value, data, recheck)
    } catch (error) {
      const code = apiErrorCode(error)
      const message = errorText(error, "Could not connect to MapSVG Dashboard. Please try again.")
      const localhostPending = code === "localhost_pending" || code === "localhost_limit"

      if (localhostPending) {
        setRawKey(value)
        setMaskedKey(maskLicenseKey(value))
        setHasCode(true)
        setEditing(false)
        setLicenseKey("")
        setStatus({
          ok: false,
          message,
          code,
          warning: "",
          warningCode: "",
          domainsUsed: null,
          domainsMax: null,
        })
      } else {
        setTransientError(message)
      }
    } finally {
      setBusy(false)
    }
  }

  const deactivate = async () => {
    if (
      !window.confirm(
        "Deactivate MapSVG license on this site? Automatic updates will stop until you activate again. This does not remove the domain from MapSVG Dashboard.",
      )
    ) {
      return
    }

    setBusy(true)
    setTransientError("")
    setSuccessMessage("")
    try {
      await deactivateLicense()
      setRawKey("")
      setMaskedKey("")
      setHasCode(false)
      setEditing(true)
      setLicenseKey("")
      setStatus({
        ok: false,
        message: "",
        code: "",
        warning: "",
        warningCode: "",
        domainsUsed: null,
        domainsMax: null,
      })
      setSuccessMessage("License deactivated on this site.")
    } catch (error) {
      setTransientError(errorText(error, "Could not deactivate the license."))
    } finally {
      setBusy(false)
    }
  }

  const dashboardLink = (
    <a
      href={params.dashboardUrl || "https://mapsvg.com/dashboard"}
      target="_blank"
      rel="noreferrer"
      className="inline-flex items-center gap-1 font-medium text-primary underline underline-offset-4"
    >
      MapSVG Dashboard <ExternalLink className="size-3.5" />
    </a>
  )

  const activationFields = (
    <>
      <p className="text-sm leading-6 text-muted-foreground">
        {hasCode
          ? "Enter a new license key to replace the current one. "
          : "Enter your license key to activate MapSVG. "}
        Get your license key from {dashboardLink}.
      </p>

      <SettingsControlField id={licenseInputId} label="License key">
        <Input
          id={licenseInputId}
          value={licenseKey}
          onChange={(event) => setLicenseKey(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter" && !busy) {
              event.preventDefault()
              void validateKey(licenseKey)
            }
          }}
          placeholder="XXXX-XXXX-XXXX-XXXX"
          autoComplete="off"
          autoFocus
        />
      </SettingsControlField>

      {transientError ? (
        <Alert variant="destructive">
          <AlertDescription>{transientError}</AlertDescription>
        </Alert>
      ) : null}

      <div className="flex flex-wrap gap-2">
        <Button type="button" onClick={() => void validateKey(licenseKey)} disabled={busy}>
          {busy ? "Activating..." : "Activate"}
        </Button>
        {hasCode && !activationOnly ? (
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              setEditing(false)
              setLicenseKey("")
              setTransientError("")
            }}
            disabled={busy}
          >
            Cancel
          </Button>
        ) : null}
      </div>
    </>
  )

  if (activationOnly) {
    return (
      <div className="flex flex-col gap-4">
        {status.message && !status.ok && (hasCode || isDomainActionCode(status.code)) ? (
          <Alert variant="destructive">
            <AlertDescription>
              {status.message}
              {isDomainActionCode(status.code) ? (
                <span className="mt-1 block">Review the domain settings in {dashboardLink}.</span>
              ) : null}
            </AlertDescription>
          </Alert>
        ) : null}
        {activationFields}
      </div>
    )
  }

  return (
    <div className="flex flex-col gap-6">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">License</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Activate MapSVG on this WordPress installation to enable automatic updates.
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{hasCode && !editing ? "License status" : "Activate MapSVG"}</CardTitle>
          <CardDescription>
            {hasCode && !editing
              ? "Manage the license currently used by this site."
              : "Enter your license key to enable automatic updates."}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          {successMessage ? (
            <Alert variant="success">
              <AlertDescription>{successMessage}</AlertDescription>
            </Alert>
          ) : null}

          {hasCode && !editing ? (
            <>
              {status.message && !status.ok ? (
                <Alert variant="destructive">
                  <AlertDescription>
                    <span>{status.message}</span>
                    {isDomainActionCode(status.code) ? (
                      <span className="mt-1 block">
                        Review the domain settings in {dashboardLink}.
                      </span>
                    ) : null}
                  </AlertDescription>
                </Alert>
              ) : null}

              {status.warning || status.warningCode === "domain_limit" ? (
                <Alert variant="warning">
                  <AlertDescription>{licenseWarningText(status)}</AlertDescription>
                </Alert>
              ) : null}

              <div className="grid gap-4 rounded-lg border p-4">
                <div className="grid gap-1">
                  <span className="text-sm text-muted-foreground">License key</span>
                  <code className="text-sm font-medium">{maskedKey || "Active"}</code>
                </div>
                {params.license?.currentDomain ? (
                  <div className="grid gap-1">
                    <span className="text-sm text-muted-foreground">Registered domain</span>
                    <code className="text-sm font-medium">{params.license.currentDomain}</code>
                  </div>
                ) : null}
              </div>

              <div className="flex flex-wrap gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    setEditing(true)
                    setTransientError("")
                    setSuccessMessage("")
                  }}
                  disabled={busy}
                >
                  Change license key
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => void validateKey(rawKey, true)}
                  disabled={busy || !rawKey}
                >
                  {busy ? "Checking..." : "Recheck license"}
                </Button>
                <Button
                  type="button"
                  variant="destructive"
                  onClick={() => void deactivate()}
                  disabled={busy}
                >
                  Deactivate
                </Button>
              </div>
            </>
          ) : (
            <>{activationFields}</>
          )}

          {!hasCode && successMessage ? (
            <p className="text-sm text-muted-foreground">
              You can enter another license key above at any time.
            </p>
          ) : null}
        </CardContent>
      </Card>
    </div>
  )
}
