import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAdminParams } from "@/lib/admin-params"

type JsonObject = Record<string, unknown>

export type SupportAccessRights = {
  logs?: boolean
  wp?: boolean
  [key: string]: boolean | undefined
}

export type SupportToken = {
  id: number
  token?: string
  tokenFirstFour?: string
  createdAt?: string | null
  lastUsedAt?: string | null
  accessRights: SupportAccessRights
}

export type LicenseMutationResponse = {
  warning?: string
  warningCode?: string
  domainsUsed?: number | null
  domainsMax?: number | null
}

export const LICENSE_CHANGED_EVENT = "mapsvg:license-changed"

function updateLicenseBootstrap(key: string, data?: LicenseMutationResponse): void {
  const params = window.mapsvgReactAdminParams
  if (!params) return
  const options = params.options
  params.options = {
    ...(options && typeof options === "object" && !Array.isArray(options) ? options : {}),
    purchase_code: key,
  }
  params.license = {
    hasCode: Boolean(key),
    maskedKey: maskLicenseKey(key),
    currentDomain: params.license?.currentDomain ?? "",
    ok: Boolean(key),
    message: "",
    code: "",
    warning: data?.warning ?? "",
    warningCode: data?.warningCode ?? "",
    domainsUsed: data?.domainsUsed ?? null,
    domainsMax: data?.domainsMax ?? null,
  }
  params.ai = { ...params.ai, configured: Boolean(key), openaiConfigured: Boolean(key) }
  // This is the existing bootstrap cache, not a second license store.
  window.dispatchEvent?.(new Event(LICENSE_CHANGED_EVENT))
}

export class MapSVGApiError extends Error {
  status: number
  payload: JsonObject | null

  constructor(message: string, status: number, payload: JsonObject | null) {
    super(message)
    this.name = "MapSVGApiError"
    this.status = status
    this.payload = payload
  }
}

function apiBase(): { base: string; nonce: string } {
  const params = getAdminParams()
  return {
    base: params.apiUrl.replace(/\/?$/, ""),
    nonce: params.nonce,
  }
}

function errorMessage(payload: JsonObject | null, fallback: string): string {
  if (!payload) return fallback
  if (typeof payload.error === "string" && payload.error) return payload.error
  if (typeof payload.message === "string" && payload.message) return payload.message
  const data = payload.data
  if (data && typeof data === "object") {
    const nested = data as JsonObject
    if (typeof nested.error === "string" && nested.error) return nested.error
    if (typeof nested.message === "string" && nested.message) return nested.message
  }
  return fallback
}

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const { base, nonce } = apiBase()
  const rel = path.startsWith("/") ? path : `/${path}`
  const headers = new Headers(init.headers)
  headers.set("Accept", "application/json")
  headers.set("X-WP-Nonce", nonce)
  if (init.body != null && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json")
  }

  const response = await adminRestFetch(`${base}${rel}`, {
    ...init,
    headers,
    credentials: "same-origin",
  })
  const payload = (await response.json().catch(() => null)) as JsonObject | null

  if (!response.ok) {
    throw new MapSVGApiError(
      errorMessage(payload, `API ${response.status}: ${path}`),
      response.status,
      payload,
    )
  }

  return payload as T
}

export function normalizeAllowedShortcodes(value: unknown): string[] {
  const raw = Array.isArray(value)
    ? value.map((item) => String(item))
    : typeof value === "string"
      ? value.split(",")
      : []

  return [...new Set(raw.map((item) => item.trim()).filter(Boolean))]
}

export function maskLicenseKey(key: string): string {
  const value = key.trim()
  if (!value) return ""
  const match = value.match(/^(?:[^-]+-){3}([^-]+)$/)
  if (match) return `****-****-****-${match[1]}`
  if (value.length <= 4) return "*".repeat(value.length)
  return `${"*".repeat(value.length - 4)}${value.slice(-4)}`
}

export function buildSupportMagicLink(homeUrl: string, token: SupportToken): string {
  const rawToken = token.token?.trim()
  if (!rawToken) return ""

  const base = homeUrl.replace(/\/$/, "")
  if (token.accessRights.wp) {
    return `${base}/_mapsvg/login?key=${encodeURIComponent(rawToken)}`
  }
  if (token.accessRights.logs) {
    return `${base}/_mapsvg/logs?key=${encodeURIComponent(rawToken)}`
  }
  return ""
}

export async function saveGlobalOptions(options: Record<string, unknown>): Promise<JsonObject> {
  const submitted = { ...options }
  const response = await request<JsonObject>("/options/", {
    method: "POST",
    body: JSON.stringify({
      options: JSON.stringify(submitted),
    }),
  })
  const params = window.mapsvgReactAdminParams
  if (params) {
    const googleKeys: JsonObject = {}
    for (const key of ["google_api_key", "google_geocoding_api_key"]) {
      if (Object.prototype.hasOwnProperty.call(submitted, key)) googleKeys[key] = submitted[key]
    }
    if (Object.keys(googleKeys).length > 0) {
      const current = params.options
      params.options = {
        ...(current && typeof current === "object" && !Array.isArray(current) ? current : {}),
        ...googleKeys,
      }
    }
  }
  return response
}

export async function listSupportTokens(): Promise<SupportToken[]> {
  const data = await request<{ items?: SupportToken[] } | SupportToken[]>("/tokens")
  if (Array.isArray(data)) return data
  return Array.isArray(data.items) ? data.items : []
}

export async function createSupportToken(accessRights: SupportAccessRights): Promise<SupportToken> {
  const data = await request<{ token?: SupportToken }>("/tokens", {
    method: "POST",
    body: JSON.stringify({
      token: { accessRights },
    }),
  })
  if (!data.token) {
    throw new Error("MapSVG did not return the created access token.")
  }
  return data.token
}

export async function deleteSupportToken(id: number): Promise<void> {
  await request<JsonObject>(`/tokens/${id}`, {
    method: "DELETE",
  })
}

export async function activateLicense(licenseKey: string): Promise<LicenseMutationResponse> {
  const data = await request<LicenseMutationResponse>("/purchasecode", {
    method: "PUT",
    body: JSON.stringify({ purchase_code: licenseKey }),
  })
  updateLicenseBootstrap(licenseKey.trim(), data)
  return data
}

export async function deactivateLicense(): Promise<void> {
  await request<JsonObject>("/purchasecode", {
    method: "DELETE",
  })
  updateLicenseBootstrap("")
}

